<?php
namespace App\Services\BoxOffice;use App\Models\BoxOfficeShift;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class BoxOfficeShiftService{
 public function open(int $organizerId,int $staffId,int $eventId,int $locationId,int $openingCash):BoxOfficeShift{return DB::transaction(function()use($organizerId,$staffId,$eventId,$locationId,$openingCash){if(BoxOfficeShift::where('staff_id',$staffId)->where('status','open')->lockForUpdate()->exists())throw ValidationException::withMessages(['shift'=>'Close the current shift before opening another.']);return BoxOfficeShift::create(['organizer_id'=>$organizerId,'staff_id'=>$staffId,'event_id'=>$eventId,'location_id'=>$locationId,'opening_cash'=>$openingCash,'opened_at'=>now()]);});}
 public function close(BoxOfficeShift $shift,int $declared):BoxOfficeShift{return DB::transaction(function()use($shift,$declared){$shift=BoxOfficeShift::whereKey($shift->id)->where('status','open')->lockForUpdate()->firstOrFail();$cash=(int)$shift->sales()->where('status','completed')->where('payment_method','cash')->sum('customer_total');$expected=$shift->opening_cash+$cash;$shift->update(['status'=>'closed','declared_closing_cash'=>$declared,'expected_cash'=>$expected,'variance'=>$declared-$expected,'closed_at'=>now()]);return $shift;});}
 public function verify(BoxOfficeShift $shift,?int $staffId,?int $organizerId,string $note=''):BoxOfficeShift{if($shift->status!=='closed')throw ValidationException::withMessages(['shift'=>'Only closed shifts can be verified.']);$shift->update(['status'=>'verified','verified_by_staff_id'=>$staffId,'verified_by_organizer_id'=>$organizerId,'verified_at'=>now(),'verification_note'=>$note]);return $shift;}
}